import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Load mesh from GLB via cached loader
  const glb = ctx.glbLoader.load('/prism-mock/home/nodes/cta-hero.glb');
  const mesh = glb.scene.clone();

  // Apply scene transforms from config
  const scenePosition = config.scenePosition || [-2.5, 0.7, 0];
  const rotation = config.rotation || [0, 0, 0];
  const scale = config.scale || [1, 1, 1];

  mesh.position.fromArray(scenePosition);
  mesh.rotation.fromArray(rotation);
  mesh.scale.fromArray(scale);

  // Store base Y position for hover animation
  const baseY = mesh.position.y;

  // Animation state
  let hoverAnimation = null;

  // Event handlers
  mesh.userData.handlers = {};

  // Hover: rise 0.15 units with power3.out easing
  mesh.userData.handlers.onHover = () => {
    if (hoverAnimation) hoverAnimation.kill();
    hoverAnimation = gsap.to(mesh.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Hover end: return to base position
  mesh.userData.handlers.onHoverEnd = () => {
    if (hoverAnimation) hoverAnimation.kill();
    hoverAnimation = gsap.to(mesh.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click: emit hub-home.select event
  mesh.userData.handlers.onClick = () => {
    mesh.dispatchEvent({ type: 'hub-home.select' });
  };

  // Data binding metadata
  mesh.userData.dataBindings = {
    confirmPanel: 'trpc.visits.book.slot'
  };

  // Cleanup: dispose geometries, materials, and kill timelines
  mesh.userData.cleanup = () => {
    if (hoverAnimation) {
      hoverAnimation.kill();
    }

    mesh.traverse((child) => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(material => material.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return mesh;
}
